namespace sv_78c9b9b5844249a2b7b15e2420dd2c64.Services;

public record Channel(int Id, string Name, string Description, int UnreadCount);
public record Message(int Id, int ChannelId, string Author, string Content, DateTime SentAt, int? ReplyToId, List<Reaction> Reactions);
public record Reaction(string Emoji, List<string> Users);
public record ThreadSummary(int RootMessageId, int ReplyCount, DateTime LastReplyAt);

public interface IChatService
{
    Task<List<Channel>> GetChannelsAsync();
    Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take);
    Task<Message> SendMessageAsync(int channelId, string content, int? replyToId);
    Task<List<Message>> GetThreadAsync(int rootMessageId);
    Task AddReactionAsync(int messageId, string emoji);
    Task MarkChannelReadAsync(int channelId);
}

@using sv_78c9b9b5844249a2b7b15e2420dd2c64.Services

<div class="channel-item @(IsActive ? "active" : "")" @onclick="HandleClick">
    <div class="channel-name"># @Channel.Name</div>
    <div class="channel-description">@Channel.Description</div>
    @if (Channel.UnreadCount > 0)
    {
        <span class="unread-badge">@Channel.UnreadCount</span>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public Channel Channel { get; set; } = default!;

    [Parameter]
    public bool IsActive { get; set; }

    [Parameter]
    public EventCallback<Channel> OnSelected { get; set; }

    private async Task HandleClick()
    {
        await OnSelected.InvokeAsync(Channel);
    }
}

@using sv_78c9b9b5844249a2b7b15e2420dd2c64.Services

<div class="channel-sidebar">
    <h3 class="sidebar-title">Channels</h3>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == ActiveChannelId"
                         OnSelected="OnChannelSelected" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Channel> Channels { get; set; } = [];

    [Parameter]
    public int? ActiveChannelId { get; set; }

    [Parameter]
    public EventCallback<Channel> OnChannelSelected { get; set; }
}

@using sv_78c9b9b5844249a2b7b15e2420dd2c64.Services

<div class="message-item" @onmouseenter="() => showActions = true" @onmouseleave="() => showActions = false">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="message-reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <button class="reaction-badge" @onclick="() => HandleReaction(reaction.Emoji)">
                    @reaction.Emoji @reaction.Users.Count
                </button>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <button class="thread-link" @onclick="HandleOpenThread">
            @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </button>
    }

    @if (showActions)
    {
        <div class="message-actions">
            <button class="action-btn" @onclick="HandleOpenThread" title="Reply in thread">💬 Reply</button>
            <button class="action-btn" @onclick="ToggleEmojiPicker" title="Add reaction">😀 React</button>
        </div>
    }

    @if (showEmojiPicker)
    {
        <div class="emoji-picker">
            @foreach (var emoji in commonEmojis)
            {
                <button class="emoji-btn" @onclick="() => HandleReaction(emoji)">@emoji</button>
            }
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public Message Message { get; set; } = default!;

    [Parameter]
    public int ReplyCount { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private bool showActions;
    private bool showEmojiPicker;
    private static readonly string[] commonEmojis = ["👍", "❤️", "😂", "🎉", "🤔", "👀"];

    private string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }

    private async Task HandleOpenThread()
    {
        await OnOpenThread.InvokeAsync(Message.Id);
    }

    private void ToggleEmojiPicker()
    {
        showEmojiPicker = !showEmojiPicker;
    }

    private async Task HandleReaction(string emoji)
    {
        showEmojiPicker = false;
        await OnReact.InvokeAsync((Message.Id, emoji));
    }
}

@using sv_78c9b9b5844249a2b7b15e2420dd2c64.Services

<div class="message-list" @onscroll="HandleScroll">
    @if (IsLoadingMore)
    {
        <div class="loading-indicator">Loading older messages...</div>
    }
    @foreach (var message in Messages)
    {
        <MessageItem Message="message"
                     ReplyCount="GetReplyCount(message.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact" />
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = [];

    [Parameter]
    public bool IsLoadingMore { get; set; }

    [Parameter]
    public EventCallback OnLoadOlder { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    private int GetReplyCount(int messageId)
    {
        return ThreadSummaries.TryGetValue(messageId, out var summary) ? summary.ReplyCount : 0;
    }

    private async Task HandleScroll(EventArgs e)
    {
        // Scroll-to-top triggers loading older messages.
        // In a real app, use JS interop to detect scrollTop === 0.
        // Here we expose the callback for the parent to wire up.
        await OnLoadOlder.InvokeAsync();
    }
}

@using sv_78c9b9b5844249a2b7b15e2420dd2c64.Services

<div class="message-area">
    <div class="message-area-header">
        <h2># @ChannelName</h2>
        <p class="channel-desc">@ChannelDescription</p>
    </div>

    <MessageList Messages="Messages"
                 ThreadSummaries="ThreadSummaries"
                 IsLoadingMore="IsLoadingMore"
                 OnLoadOlder="OnLoadOlder"
                 OnOpenThread="OnOpenThread"
                 OnReact="OnReact" />

    <MessageInput Placeholder="@($"Message #{ChannelName}")"
                  ButtonText="Send"
                  OnSend="OnSendMessage" />
</div>

@code {
    [Parameter, EditorRequired]
    public string ChannelName { get; set; } = string.Empty;

    [Parameter]
    public string ChannelDescription { get; set; } = string.Empty;

    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = [];

    [Parameter]
    public bool IsLoadingMore { get; set; }

    [Parameter]
    public EventCallback OnLoadOlder { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback<string> OnSendMessage { get; set; }
}

@using sv_78c9b9b5844249a2b7b15e2420dd2c64.Services

<div class="thread-panel">
    <div class="thread-header">
        <h3>Thread</h3>
        <button class="close-btn" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <span class="message-author">@RootMessage.Author</span>
            <p>@RootMessage.Content</p>
        </div>

        <div class="thread-replies">
            @foreach (var reply in ThreadMessages)
            {
                <div class="thread-reply">
                    <div class="message-header">
                        <span class="message-author">@reply.Author</span>
                        <span class="message-time">@FormatRelativeTime(reply.SentAt)</span>
                    </div>
                    <div class="message-content">@reply.Content</div>
                </div>
            }
        </div>

        <MessageInput Placeholder="Reply in thread..."
                      ButtonText="Reply"
                      OnSend="OnReply" />
    }
</div>

@code {
    [Parameter]
    public Message? RootMessage { get; set; }

    [Parameter]
    public List<Message> ThreadMessages { get; set; } = [];

    [Parameter]
    public EventCallback OnClose { get; set; }

    [Parameter]
    public EventCallback<string> OnReply { get; set; }

    private string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours}h ago";
        if (diff.TotalDays < 7) return $"{(int)diff.TotalDays}d ago";
        return sentAt.ToString("MMM d, yyyy");
    }
}

@page "/chat"
@using sv_78c9b9b5844249a2b7b15e2420dd2c64.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannel?.Id"
                    OnChannelSelected="HandleChannelSelected" />

    <div class="chat-main @(isThreadOpen ? "thread-open" : "")">
        @if (selectedChannel is not null)
        {
            <MessageArea ChannelName="@selectedChannel.Name"
                         ChannelDescription="@selectedChannel.Description"
                         Messages="messages"
                         ThreadSummaries="threadSummaries"
                         IsLoadingMore="isLoadingMore"
                         OnLoadOlder="LoadOlderMessages"
                         OnOpenThread="HandleOpenThread"
                         OnReact="HandleReact"
                         OnSendMessage="HandleSendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     ThreadMessages="threadMessages"
                     OnClose="HandleCloseThread"
                     OnReply="HandleThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = [];
    private bool isLoadingMore;
    private const int PageSize = 30;

    // Thread state
    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await HandleChannelSelected(channels[0]);
        }
    }

    private async Task HandleChannelSelected(Channel channel)
    {
        selectedChannel = channel;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to update unread counts
        channels = await ChatService.GetChannelsAsync();

        // Build thread summaries from messages that have replies
        threadSummaries = messages
            .Where(m => m.ReplyToId is null)
            .ToDictionary(
                m => m.Id,
                m =>
                {
                    var replies = messages.Where(r => r.ReplyToId == m.Id).ToList();
                    return new ThreadSummary(m.Id, replies.Count, replies.LastOrDefault()?.SentAt ?? m.SentAt);
                })
            .Where(kv => kv.Value.ReplyCount > 0)
            .ToDictionary(kv => kv.Key, kv => kv.Value);
    }

    private async Task LoadOlderMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;

        isLoadingMore = true;
        var olderMessages = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (olderMessages.Count > 0)
        {
            messages.InsertRange(0, olderMessages);
        }
        isLoadingMore = false;
    }

    private async Task HandleSendMessage(string content)
    {
        if (selectedChannel is null) return;
        var newMessage = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(newMessage);
    }

    private async Task HandleOpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadMessages = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void HandleCloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task HandleThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        // Update thread summary
        threadSummaries[threadRootMessage.Id] = new ThreadSummary(
            threadRootMessage.Id,
            threadMessages.Count,
            reply.SentAt);
    }

    private async Task HandleReact((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to show updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messages.Count);
        }
    }
}

