@page "/chat"
@using sv_78c9b9b5844249a2b7b15e2420dd2c64.Services
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="channels"
                    ActiveChannelId="selectedChannel?.Id"
                    OnChannelSelected="HandleChannelSelected" />

    <div class="chat-main @(isThreadOpen ? "thread-open" : "")">
        @if (selectedChannel is not null)
        {
            <MessageArea ChannelName="@selectedChannel.Name"
                         ChannelDescription="@selectedChannel.Description"
                         Messages="messages"
                         ThreadSummaries="threadSummaries"
                         IsLoadingMore="isLoadingMore"
                         OnLoadOlder="LoadOlderMessages"
                         OnOpenThread="HandleOpenThread"
                         OnReact="HandleReact"
                         OnSendMessage="HandleSendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (isThreadOpen)
    {
        <ThreadPanel RootMessage="threadRootMessage"
                     ThreadMessages="threadMessages"
                     OnClose="HandleCloseThread"
                     OnReply="HandleThreadReply" />
    }
</div>

@code {
    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private List<Message> messages = [];
    private Dictionary<int, ThreadSummary> threadSummaries = [];
    private bool isLoadingMore;
    private const int PageSize = 30;

    // Thread state
    private bool isThreadOpen;
    private Message? threadRootMessage;
    private List<Message> threadMessages = [];

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();
        if (channels.Count > 0)
        {
            await HandleChannelSelected(channels[0]);
        }
    }

    private async Task HandleChannelSelected(Channel channel)
    {
        selectedChannel = channel;
        messages = await ChatService.GetMessagesAsync(channel.Id, 0, PageSize);
        await ChatService.MarkChannelReadAsync(channel.Id);

        // Refresh channels to update unread counts
        channels = await ChatService.GetChannelsAsync();

        // Build thread summaries from messages that have replies
        threadSummaries = messages
            .Where(m => m.ReplyToId is null)
            .ToDictionary(
                m => m.Id,
                m =>
                {
                    var replies = messages.Where(r => r.ReplyToId == m.Id).ToList();
                    return new ThreadSummary(m.Id, replies.Count, replies.LastOrDefault()?.SentAt ?? m.SentAt);
                })
            .Where(kv => kv.Value.ReplyCount > 0)
            .ToDictionary(kv => kv.Key, kv => kv.Value);
    }

    private async Task LoadOlderMessages()
    {
        if (selectedChannel is null || isLoadingMore) return;

        isLoadingMore = true;
        var olderMessages = await ChatService.GetMessagesAsync(selectedChannel.Id, messages.Count, PageSize);
        if (olderMessages.Count > 0)
        {
            messages.InsertRange(0, olderMessages);
        }
        isLoadingMore = false;
    }

    private async Task HandleSendMessage(string content)
    {
        if (selectedChannel is null) return;
        var newMessage = await ChatService.SendMessageAsync(selectedChannel.Id, content, null);
        messages.Add(newMessage);
    }

    private async Task HandleOpenThread(int messageId)
    {
        threadRootMessage = messages.FirstOrDefault(m => m.Id == messageId);
        if (threadRootMessage is null) return;

        threadMessages = await ChatService.GetThreadAsync(messageId);
        isThreadOpen = true;
    }

    private void HandleCloseThread()
    {
        isThreadOpen = false;
        threadRootMessage = null;
        threadMessages = [];
    }

    private async Task HandleThreadReply(string content)
    {
        if (selectedChannel is null || threadRootMessage is null) return;
        var reply = await ChatService.SendMessageAsync(selectedChannel.Id, content, threadRootMessage.Id);
        threadMessages.Add(reply);

        // Update thread summary
        threadSummaries[threadRootMessage.Id] = new ThreadSummary(
            threadRootMessage.Id,
            threadMessages.Count,
            reply.SentAt);
    }

    private async Task HandleReact((int MessageId, string Emoji) reaction)
    {
        await ChatService.AddReactionAsync(reaction.MessageId, reaction.Emoji);
        // Refresh messages to show updated reactions
        if (selectedChannel is not null)
        {
            messages = await ChatService.GetMessagesAsync(selectedChannel.Id, 0, messages.Count);
        }
    }
}

