    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #313338;
}

::deep .message-area-header h2 {
    margin: 0;
    font-size: 1.1rem;
    color: #f2f3f5;
}

::deep .channel-desc {
    margin: 4px 0 0;
    font-size: 0.8rem;
    color: #949ba4;
}

::deep .message-list {
    flex: 1;
    overflow-y: auto;
    padding: 16px;
}

::deep .loading-indicator {
    text-align: center;
