    padding: 4px;
    border-radius: 4px;
}

::deep .emoji-btn:hover {
    background: #404249;
}

/* Message input */
::deep .message-input {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #3f4147;
    background: #313338;
}

::deep .message-input textarea {
    flex: 1;
    background: #383a40;
    border: none;
    border-radius: 8px;
    padding: 10px 12px;
    color: #dbdee1;
    font-size: 0.9rem;
    resize: none;
    font-family: inherit;
}

::deep .message-input textarea::placeholder {
    color: #6d6f78;
}

::deep .send-btn {
    background: #5865f2;
