::deep .thread-header h3 {
    margin: 0;
    color: #f2f3f5;
    font-size: 1rem;
}

::deep .close-btn {
    background: none;
    border: none;
    color: #b5bac1;
    font-size: 1.2rem;
    cursor: pointer;
    padding: 4px 8px;
    border-radius: 4px;
}

::deep .close-btn:hover {
    background: #404249;
    color: #f2f3f5;
}

::deep .thread-root-message {
    padding: 12px 16px;
    border-bottom: 1px solid #3f4147;
    background: #232428;
}

::deep .thread-root-message p {
    margin: 6px 0 0;
    font-size: 0.85rem;
    color: #b5bac1;
}

::deep .thread-replies {
    flex: 1;
    overflow-y: auto;
    padding: 12px 16px;
}

::deep .thread-reply {
    margin-bottom: 12px;
    padding: 6px 0;
}

/* No channel selected state */
.no-channel-selected {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: #949ba4;
    font-size: 1.1rem;
}

