+::deep .action-btn:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+::deep .emoji-picker {
+    display: flex;
+    gap: 4px;
+    background: #2b2d31;
+    border: 1px solid #3f4147;
+    border-radius: 6px;
+    padding: 8px;
+    margin-top: 4px;
+    width: fit-content;
+}
+
+::deep .emoji-btn {
+    background: none;
+    border: none;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px;
+    border-radius: 4px;
+}
+
+::deep .emoji-btn:hover {
+    background: #404249;
+}
+
+/* Message input */
+::deep .message-input {
+    display: flex;
+    gap: 8px;
+    padding: 12px 16px;
+    border-top: 1px solid #3f4147;
+    background: #313338;
+}
+
+::deep .message-input textarea {
+    flex: 1;
+    background: #383a40;
+    border: none;
+    border-radius: 8px;
+    padding: 10px 12px;
+    color: #dbdee1;
+    font-size: 0.9rem;
+    resize: none;
+    font-family: inherit;
+}
+
+::deep .message-input textarea::placeholder {
+    color: #6d6f78;
+}
+
+::deep .send-btn {
+    background: #5865f2;
+    color: white;
+    border: none;
+    border-radius: 8px;
+    padding: 8px 16px;
+    font-weight: 600;
+    cursor: pointer;
+    align-self: flex-end;
+}
+
+::deep .send-btn:hover:not(:disabled) {
+    background: #4752c4;
+}
+
+::deep .send-btn:disabled {
+    opacity: 0.5;
+    cursor: not-allowed;
+}
+
+/* Thread panel */
+::deep .thread-panel {
+    width: 25%;
+    min-width: 280px;
+    background: #2b2d31;
+    border-left: 1px solid #1e1f22;
+    display: flex;
+    flex-direction: column;
+    color: #dbdee1;
+}
+
+::deep .thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 12px 16px;
+    border-bottom: 1px solid #3f4147;
+}
+
+::deep .thread-header h3 {
+    margin: 0;
+    color: #f2f3f5;
+    font-size: 1rem;
+}
+
+::deep .close-btn {
+    background: none;
+    border: none;
+    color: #b5bac1;
+    font-size: 1.2rem;
+    cursor: pointer;
+    padding: 4px 8px;
+    border-radius: 4px;
+}
+
+::deep .close-btn:hover {
+    background: #404249;
+    color: #f2f3f5;
+}
+
+::deep .thread-root-message {
+    padding: 12px 16px;
+    border-bottom: 1px solid #3f4147;
+    background: #232428;
+}
+
+::deep .thread-root-message p {
+    margin: 6px 0 0;
+    font-size: 0.85rem;
+    color: #b5bac1;
+}
+
+::deep .thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 12px 16px;
+}
+
+::deep .thread-reply {
+    margin-bottom: 12px;
+    padding: 6px 0;
+}
+
+/* No channel selected state */
+.no-channel-selected {
+    display: flex;
+    align-items: center;
+    justify-content: center;
+    height: 100%;
+    color: #949ba4;
+    font-size: 1.1rem;
+}
